/* Minimal local HTMX-compatible form adapter for MVP; replace with audited upstream bundle when packaging release. */
document.addEventListener('submit',async e=>{const f=e.target;if(!f.matches('[hx-post]'))return;e.preventDefault();const target=document.querySelector(f.getAttribute('hx-target'));f.classList.add('htmx-request');try{const r=await fetch(f.getAttribute('hx-post'),{method:'POST',body:new FormData(f)});target.innerHTML=await r.text()}finally{f.classList.remove('htmx-request')}});